class Circle:
    def __init__(self, radius):
        self._radius = 0 # Initialize to default or validate via setter
        self.radius = radius # Use setter for initial validation

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("Radius must be a number.")
        if value < 0:
            raise ValueError("Radius cannot be negative.")
        self._radius = value
