class User:
    def __init__(self, username):
        self._username = username

    @property
    def username(self):
        return self._username

    @username.setter
    def username(self, value):
        if not value:
            raise ValueError("Username cannot be empty.")
        self._username = value

    @username.deleter
    def username(self):
        print(f"Deleting username for {self._username}...")
        del self._username
        # Or set to None, log, etc.

# Scenario: When a user account needs to be anonymized or deleted, the deleter can handle
# associated cleanup, logging, or GDPR compliance by removing sensitive data like the username.
